<ul>
  <li>Quem são os Caboclos (detalhado)</li>
  <li>Quem são os Pretos-Velhos (detalhado)</li>
  <li>Crianças, Baianos, Marinheiros, Boiadeiros</li>
  <li>Exus e Pombagiras</li>
  <li>Como cada entidade trabalha</li>
  <li>Respeito e não folclorização</li>

</ul>
